// Actions de paiement
const initiatePayment = async (paymentData) => {
  if (!isOnline) {
    // Stocker la demande mais la bloquer
    queueManager.addToQueue({
      id: 'payment_' + Date.now(),
      type: 'payment',
      data: paymentData,
      requiresOnline: true, // La requête nécessite une connexion
    });
    showToast(
